CREATE OR REPLACE FUNCTION public.icash_open_seller_gap(p_account uuid, p_thread uuid, p_source text, p_source_id uuid, p_reason text, p_quote text, p_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;d public.icash_deal_files;new_id uuid;initial text;due timestamptz;
begin
 select * into t from public.icash_text_threads where id=p_thread and account_id=p_account and party='seller' and retired_at is null;
 if not found or p_source_id is null or p_at is null or p_at>now() or p_at<now()-interval '7 days' then return null;end if;
 select * into d from public.icash_deal_files where id=t.deal_id and account_id=p_account and stage not in ('closed','cancelled') and coalesce(terms->>'practice','false')<>'true';
 if not found or p_reason is null then return null;end if;
 initial:=case when p_reason='contact_stop' then 'suppressed' when p_reason in ('human','declined','owners','material_facts','callback','delivery_unknown') then 'needs_review' else 'open' end;
 -- Clarify once. An unresolved reply after a recovery is a human task, not a loop.
 if p_reason in ('unanswered','repeated_question') and exists(select 1 from public.icash_seller_recovery_attempts where account_id=p_account and thread_id=t.id and reason in ('unanswered','repeated_question') and assigned_at>now()-interval '7 days') then initial:='needs_review';end if;
 due:=greatest(now(),p_at+case when p_reason='no_response' then interval '24 hours' else interval '2 minutes' end);

 -- Operational observations currently last 24 hours from their original source.
 -- Allow one same-day continuation; a missed window needs new contact checks.
 if p_reason='no_response' and t.operational_contact_id is not null then
  due:=greatest(now(),p_at+case when exists(select 1 from icash_seller_recovery_private.unanswered_policy policy where policy.id=1 and policy.enabled and p_at>=policy.activated_at) then interval '4 hours' else interval '3 days' end);
  if t.eligibility_until is null or due>=t.eligibility_until then initial:='needs_review';end if;
 end if;
 insert into public.icash_seller_gaps(account_id,deal_id,screening_id,thread_id,source,source_id,reason,stage,channel,quote,state,due_at,expires_at,source_at)
 values(p_account,d.id,d.screening_id,t.id,p_source,p_source_id,p_reason,d.stage,case when p_source in ('call','inbound_call','tool') then 'call' else 'text' end,left(coalesce(p_quote,''),1000),initial,due,p_at+interval '7 days',p_at)
 on conflict(source,source_id,reason) do nothing returning icash_seller_gaps.id into new_id;

 if new_id is not null and initial='needs_review' and p_reason='no_response' and t.operational_contact_id is not null then
  update public.icash_seller_gaps set review_reason='contact_checks_expired' where id=new_id;
 end if;
 return new_id;
end $function$

CREATE OR REPLACE FUNCTION public.icash_queue_unanswered_seller_calls()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare candidate record;created integer:=0;added integer;visited boolean:=false;
begin
 perform pg_advisory_xact_lock(726341927);
 perform 1 from public.icash_operating_budget where id=1 and enabled for update;if not found then return 0;end if;
 for candidate in
  select j.id,j.account_id,j.operational_contact_id,r.id recording_id,r.dial_claimed_at from public.icash_call_recordings r
  join public.icash_voice_jobs j on j.id=r.voice_job_id and j.account_id=r.account_id
  join public.icash_operational_contacts c on c.id=j.operational_contact_id and c.account_id=j.account_id
  join public.icash_accounts a on a.id=j.account_id and not a.bot_paused
  join public.icash_wallets w on w.account_id=j.account_id and w.balance_cents>w.reserved_cents
  join icash_seller_recovery_private.unanswered_policy policy on policy.id=1 and policy.enabled
  where j.seller_followup_of is null and j.state='dispatched' and j.created_at>=policy.activated_at
   and r.dial_claimed_at between greatest(policy.activated_at,now()-interval '24 hours') and now()-interval '2 hours'
   and c.eligibility_until>now() and c.revoked_at is null
   and (policy.scan_at is null or (r.dial_claimed_at,r.id)>(policy.scan_at,policy.scan_id))
   and not exists(select 1 from public.icash_voice_jobs f where f.seller_followup_of=j.id)
  order by r.dial_claimed_at,r.id limit 20
 loop
  visited:=true;
  update icash_seller_recovery_private.unanswered_policy set scan_at=candidate.dial_claimed_at,scan_id=candidate.recording_id where id=1;
  if public.icash_unanswered_seller_call_current(candidate.account_id,candidate.id) then
   insert into public.icash_voice_jobs(account_id,operational_contact_id,seller_followup_of,due_at)
    values(candidate.account_id,candidate.operational_contact_id,candidate.id,clock_timestamp()) on conflict do nothing;
   get diagnostics added=row_count;created:=created+added;
  end if;
 end loop;
 if not visited then update icash_seller_recovery_private.unanswered_policy set scan_at=null,scan_id=null where id=1;end if;
 return created;
end $function$

CREATE OR REPLACE FUNCTION public.icash_seller_phone_call_current(p_account uuid, p_job uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_voice_jobs;p public.icash_voice_contact_targets;n bigint;last_attempt timestamptz;unknown_attempt boolean;
begin
 select * into j from public.icash_voice_jobs where id=p_job and account_id=p_account;
 if not found then return false;end if;
 select * into p from public.icash_voice_contact_targets
 where id=coalesce(j.permission_id,j.operational_contact_id) and account_id=p_account and party='seller'
 and ((j.permission_id is not null and j.operational_contact_id is null and eligibility_source='operator_record')
  or (j.permission_id is null and j.operational_contact_id is not null and eligibility_source='operational_checks_only'));
 if not found or p.phone is null or p.phone !~ '^\+[1-9][0-9]{7,14}$' then return false;end if;
 if exists(select 1 from public.icash_call_recordings r where r.voice_job_id=p_job
  and (r.account_id is distinct from p_account or r.to_phone is distinct from p.phone)) then return false;end if;
 select count(*),max(at),coalesce(bool_or(unknown),false) into n,last_attempt,unknown_attempt from (
  select r.dial_claimed_at at,(r.call_sid is null and r.call_ended_at is null) unknown
  from public.icash_call_recordings r
  where r.party='seller' and r.to_phone=p.phone and r.voice_job_id is distinct from p_job and r.dial_claimed_at is not null
   and (r.dial_claimed_at>now()-interval '24 hours' or (r.call_sid is null and r.call_ended_at is null))
  union all
  select c.created_at,false from public.icash_customer_phone_calls c
  where c.recipient_phone=p.phone and c.child_sid is not null and c.created_at>now()-interval '24 hours'
 ) attempts;
 if unknown_attempt then return false;end if;
 if j.seller_followup_of is not null then
  return n=1 and last_attempt<=clock_timestamp()-interval '2 hours'
   and public.icash_unanswered_seller_call_current(p_account,j.seller_followup_of,p_job);
 end if;
 -- Real active conversations, due requested callbacks and validated notices
 -- retain the existing receipt-bound service path. A job flag is not proof.
 if coalesce(public.icash_voice_outreach_context(p_account,p_job)->>'activeConversation','false')='true'
  or public.icash_requested_seller_call_current(p_account,p_job) then return true;end if;
 -- A completed address response followed by a ready cash offer is existing
 -- seller work. Bind it to the original lead, permission, phone and actual call.
 if j.meta_offer_lead_id is not null and exists(
  select 1 from public.icash_meta_leads m
  join public.icash_seller_intakes l on l.id=m.lead_id and l.phone=p.phone
  join public.icash_contact_permissions cp on cp.id=j.permission_id and cp.account_id=m.account_id
   and cp.seller_intake_id=m.lead_id and cp.screening_id=m.screening_id and cp.phone=l.phone
  join public.icash_call_recordings first_call on first_call.voice_job_id=m.voice_job_id
   and first_call.account_id=m.account_id and first_call.to_phone=l.phone and first_call.call_sid is not null
  where m.lead_id=j.meta_offer_lead_id and m.account_id=p_account and m.screening_id=p.screening_id
   and m.address_confirmed_at>=first_call.dial_claimed_at and m.address_confirmed_at<=now()
   and m.offer_ready_at>=m.address_confirmed_at and m.offer_ready_at<=now()
   and m.offer_authorized_at is null and not m.paused and not m.voice_paused and m.declined_at is null
   and cp.revoked_at is null and cp.permission_until>now()
 ) then return true;end if;
 if j.meta_followup_lead_id is not null then
  return n<2 and (last_attempt is null or last_attempt<=now()-interval '2 hours')
   and public.icash_meta_followup_call_current(j.meta_followup_lead_id,p_job);
 end if;
 -- Owner self-demonstrations require their own fresh form receipt even when
 -- the rolling-day window clears. Expired requests cannot dial tomorrow.
 if p_account='48dfb798-8c1a-404f-88c0-c396cc067062'::uuid and p.phone='+12142185280'
  and exists(select 1 from public.icash_contact_permissions cp
   join public.icash_seller_intakes l on l.id=cp.seller_intake_id
   where cp.id=j.permission_id and cp.account_id=p_account and l.contact_consent_scope='icash_x_demo') then
  return public.icash_owner_demo_call_current(p_account,p_job);
 end if;
 -- One new automatic introduction per phone per rolling day. Other properties
 -- do not create permission to call the same person again immediately.
 return n=0;
end $function$

CREATE OR REPLACE FUNCTION public.icash_seller_text_cadence_current(p_account uuid, p_thread uuid, p_message uuid DEFAULT NULL::uuid, p_followup boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;d public.icash_deal_files;last_body text;n integer;first_at timestamptz;original_thread uuid;
begin
 select * into t from public.icash_text_threads where id=p_thread and account_id=p_account;
 if not found then return false;end if;
 if t.party<>'seller' then return true;end if;
 -- Human-authored sends and verified cancellation workflows retain their own
 -- final consent/suppression gates. A draft is never an incoming response.
 if p_message is not null and exists(select 1 from public.icash_text_messages m
  where m.id=p_message and m.thread_id=t.id and m.account_id=p_account
   and (m.customer_author_id is not null or exists(select 1 from public.icash_cancellation_notices c where c.account_id=p_account and c.sms_id=m.id))) then return true;end if;
 -- Requested-contact flows keep their separately verified source-bound sequence.
 -- This field does not grant consent: their existing final evidence gate still runs.
 if t.seller_intake_id is not null and t.operational_contact_id is null then return true;end if;
 select * into d from public.icash_deal_files where id=t.deal_id and account_id=p_account;
 if not found then return false;end if;
 -- Continue source-backed human replies and ongoing signed work normally.
 if d.stage not in ('draft','cancelled','closed') then return true;end if;
 if exists(select 1 from public.icash_text_messages m where m.thread_id=t.id and m.account_id=p_account
  and m.direction='incoming' and m.state='received' and (m.provider_id is not null or m.event_id is not null)
  and m.created_at between now()-interval '24 hours' and now()
  and m.body ~ '[[:alnum:]]' and m.body !~* '(^Free Msg:|Message Blocking is active|verification code|one.time (password|code))'
  and public.icash_seller_response_disposition(m.body) is null)
 or exists(select 1 from public.icash_live_conversations c where c.account_id=p_account and c.screening_id=d.screening_id
  and c.contact_key=encode(sha256(convert_to(t.recipient,'UTF8')),'hex') and c.state='complete'
  and c.completed_at between now()-interval '24 hours' and now() and c.conversation_id is not null
  and public.icash_call_has_seller_response(c.result)) then return true;end if;
 -- Natural refusals on another property cannot restart automated cold pursuit.
 select m.body into last_body from public.icash_text_threads other
 join public.icash_text_messages m on m.thread_id=other.id and m.account_id=other.account_id
 where other.recipient=t.recipient and other.party='seller' and m.direction='incoming'
  and m.state='received' and (m.provider_id is not null or m.event_id is not null)
 order by m.created_at desc,m.id desc limit 1;
 if public.icash_seller_response_disposition(last_body) is not null then return false;end if;
 -- Include every business number, property and account, including retired history.
 -- Unknown or already reserved sends cannot be treated as an unused introduction.
 if exists(select 1 from public.icash_text_threads other
  join public.icash_text_messages m on m.thread_id=other.id and m.account_id=other.account_id
  left join public.icash_operation_spend o on o.operation_key='text:'||m.id and o.account_id=m.account_id
  where other.recipient=t.recipient and other.party='seller' and m.direction='outgoing' and m.id is distinct from p_message
   and (m.state in ('dispatching','needs_review') or (m.provider_id is null and o.state in ('reserved','dispatched')))) then return false;end if;
 select count(*),min(sent.at) into n,first_at from (
  select m.thread_id,coalesce(o.dispatched_at,m.created_at) at
  from public.icash_text_threads other
  join public.icash_text_messages m on m.thread_id=other.id and m.account_id=other.account_id
  left join public.icash_operation_spend o on o.operation_key='text:'||m.id and o.account_id=m.account_id
  where other.recipient=t.recipient and other.party='seller' and m.direction='outgoing' and m.id is distinct from p_message
   and (m.provider_id is not null or o.dispatched_at is not null)
  limit 2
 ) sent;
 if n=0 then return not p_followup;end if;
 if n<>1 or not p_followup or first_at>now()-(case when exists(select 1 from icash_seller_recovery_private.unanswered_policy policy where policy.id=1 and policy.enabled and first_at>=policy.activated_at) then interval '4 hours' else interval '3 days' end)
  or first_at<now()-(case when exists(select 1 from icash_seller_recovery_private.unanswered_policy policy where policy.id=1 and policy.enabled and first_at>=policy.activated_at) then interval '24 hours' else interval '5 days' end) then return false;end if;
 select m.thread_id into original_thread from public.icash_text_threads other
 join public.icash_text_messages m on m.thread_id=other.id and m.account_id=other.account_id
 left join public.icash_operation_spend o on o.operation_key='text:'||m.id and o.account_id=m.account_id
 where other.recipient=t.recipient and other.party='seller' and m.direction='outgoing' and m.id is distinct from p_message
  and (m.provider_id is not null or o.dispatched_at is not null) limit 1;
 return original_thread=t.id;
end $function$

CREATE OR REPLACE FUNCTION public.icash_meta_prepare_followups(p_lead uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare m public.icash_meta_leads;p public.icash_contact_permissions;j public.icash_voice_jobs;msg uuid;texts jsonb:='[]';call_id uuid;purpose text;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into m from public.icash_meta_leads where lead_id=p_lead for update;
 if not found then return null;end if;
 foreach purpose in array array['followup_1','followup_2'] loop
  if public.icash_meta_followup_current(p_lead,purpose) then
   msg:=public.icash_meta_queue_message(p_lead,purpose,'v1','Follow-up');
   if exists(select 1 from public.icash_text_messages where id=msg and account_id=m.account_id and state='ready' and provider_id is null) then
    texts:=texts||jsonb_build_array(msg);
   end if;
  end if;
 end loop;
 if public.icash_meta_followup_current(p_lead,'call') and public.icash_outreach_voice_current(m.account_id) then
  select cp.* into p from public.icash_contact_permissions cp join public.icash_voice_jobs first_job on first_job.permission_id=cp.id
   where first_job.id=m.voice_job_id and cp.account_id=m.account_id and cp.seller_intake_id=m.lead_id and cp.screening_id=m.screening_id;
  if p.id is not null and public.icash_seller_voice_permission_current(m.account_id,p.id)
   and not exists(select 1 from public.icash_voice_jobs v where v.permission_id=p.id and v.meta_followup_lead_id is null
    and (v.state in ('ready','issued','dispatching') or v.state='held' and v.outcome in ('provider_receipt_needs_reconciliation','provider_outcome_unknown_no_retry'))) then
   insert into public.icash_voice_jobs(account_id,permission_id,meta_followup_lead_id) values(m.account_id,p.id,m.lead_id) on conflict do nothing;
   select * into j from public.icash_voice_jobs where meta_followup_lead_id=m.lead_id and account_id=m.account_id for update;
   if j.state in ('ready','issued') and j.due_at<=now() and j.provider_call_sid is null and j.conversation_id is null
    and not exists(select 1 from public.icash_operation_spend where operation_key='voice:'||j.id) then
    update public.icash_voice_jobs set state='issued',updated_at=now() where id=j.id;
    call_id:=j.id;
   end if;
  end if;
 end if;
 return jsonb_build_object('accountId',m.account_id,'messageIds',texts,'voiceJobId',call_id);
end $function$

CREATE OR REPLACE FUNCTION public.icash_observe_seller_recovery_text()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;reason text;
begin
 if TG_OP='UPDATE' and icash_text_receipt_private.canonical_update(old,new) then
  if new.state='delivered' then
   update public.icash_seller_recovery_attempts set delivered_at=coalesce(delivered_at,new.last_delivery_at) where account_id=new.account_id and message_id=new.id;
  end if;
  return new;
 end if;
 select * into t from public.icash_text_threads where id=new.thread_id and account_id=new.account_id and party='seller';if not found then return new;end if;
 if new.direction='incoming' and new.state='received' and tg_op='INSERT' then
  update public.icash_seller_recovery_attempts set responded_at=coalesce(responded_at,new.created_at),opted_out_at=case when public.icash_seller_contact_stop(new.body) then coalesce(opted_out_at,new.created_at) else opted_out_at end
   where account_id=t.account_id and thread_id=t.id and delivered_at is not null and delivered_at<=new.created_at;
  update public.icash_seller_gaps set state=case when public.icash_seller_contact_stop(new.body) then 'suppressed' else 'superseded' end,updated_at=now()
   where account_id=t.account_id and thread_id=t.id and state in ('open','queued','waiting') and created_at<new.created_at;
  -- A response ends the old reminder. The existing intake processes its content;
  -- it is not marked as a resolved question, accepted offer or signed agreement.
 elsif new.direction='outgoing' then
  if new.state='delivered' and new.provider_id is not null then
   update public.icash_seller_recovery_attempts set delivered_at=coalesce(delivered_at,new.last_delivery_at,now()) where account_id=t.account_id and message_id=new.id;
   update public.icash_seller_gaps set state='waiting',updated_at=now() where account_id=t.account_id and outgoing_id=new.id and state='queued';
   if not exists(select 1 from public.icash_seller_recovery_attempts where message_id=new.id) and new.body like '%?%'
    and exists(select 1 from public.icash_deal_files where id=t.deal_id and account_id=t.account_id and stage='draft') then
    perform public.icash_open_seller_gap(t.account_id,t.id,'text',new.id,'no_response','No reply to delivered question',coalesce(new.last_delivery_at,now()));
   end if;
  elsif new.state='needs_review' then
   update public.icash_seller_gaps set state='needs_review',updated_at=now() where account_id=t.account_id and outgoing_id=new.id and state in ('queued','waiting');
   perform public.icash_open_seller_gap(t.account_id,t.id,'text',new.id,'delivery_unknown','Delivery needs reconciliation; do not resend',now());
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_seller_recovery_current(p_gap uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare g public.icash_seller_gaps;t public.icash_text_threads;d public.icash_deal_files;anchor timestamptz;
begin
 select * into g from public.icash_seller_gaps where id=p_gap and state in ('open','queued') and expires_at>now();if not found then return false;end if;
 select * into t from public.icash_text_threads where id=g.thread_id and account_id=g.account_id and deal_id=g.deal_id and party='seller' and not paused and not manual_only and retired_at is null and ai_mode='auto';if not found then return false;end if;
 if not exists(select 1 from public.icash_accounts where id=g.account_id and not bot_paused) then return false;end if;
 select * into d from public.icash_deal_files where id=g.deal_id and account_id=g.account_id and stage=g.stage and coalesce(terms->>'practice','false')<>'true';if not found then return false;end if;
 -- A non-price continuation reminder does not need a new valuation purchase.
 -- It still needs the original bound seller consent and current contact controls.
 if public.icash_seller_conversation_context(g.account_id,t.id) is null and not(g.reason='no_response' and d.stage='draft' and (public.icash_seller_sms_permission_current(g.account_id,t.id,false) is true
  or (t.operational_contact_id is not null and public.icash_sms_thread_review_current(g.account_id,t.id,false) is true))) then return false;end if;
 if not public.icash_seller_text_cadence_current(g.account_id,t.id,g.outgoing_id,g.reason='no_response') then return false;end if;
 anchor:=g.source_at;
 if g.source='text_ai' then select m.created_at into anchor from public.icash_text_ai_jobs j join public.icash_text_messages m on m.id=j.message_id and m.account_id=j.account_id where j.id=g.source_id and j.account_id=g.account_id and j.thread_id=t.id and j.outgoing_id is null and j.state in ('drafted','needs_review');if not found then return false;end if;
 elsif g.source='text' then select created_at into anchor from public.icash_text_messages where id=g.source_id and account_id=g.account_id and thread_id=t.id;if not found then return false;end if;
 end if;
 if exists(select 1 from public.icash_text_messages where account_id=g.account_id and thread_id=t.id and created_at>anchor and id is distinct from g.outgoing_id and (direction='incoming' or state in ('ready','dispatching','accepted','delivered'))) then return false;end if;
 if g.reason='no_response' and (d.stage<>'draft' or exists(select 1 from public.icash_live_callbacks where account_id=g.account_id and screening_id=d.screening_id and state in ('pending_dispatch_review','held_for_human'))) then return false;end if;
 if g.reason='viewing' and (jsonb_array_length(public.icash_current_viewing_slots(g.account_id,g.deal_id))>0 or d.stage not in ('under_contract','buyer_selected','title_open','closing')) then return false;end if;
 return not exists(select 1 from public.icash_text_suppressions where phone=t.recipient)
  and not exists(select 1 from public.icash_contact_suppressions where contact_key=encode(sha256(convert_to(t.recipient,'UTF8')),'hex'));
end $function$

CREATE OR REPLACE FUNCTION public.icash_prepare_seller_recovery(p_account uuid, p_gap uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare g public.icash_seller_gaps;v public.icash_seller_recovery_variants;mid uuid;bucket integer;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 select * into g from public.icash_seller_gaps where id=p_gap and account_id=p_account for update;
 if not found or g.state<>'open' or g.due_at>now() or g.expires_at<=now() or g.outgoing_id is not null then return null;end if;
 -- A release/operator pause is temporary, not evidence that the seller needs review.
 if not exists(select 1 from public.icash_seller_recovery_variants where reason=g.reason and enabled) then return null;end if;
 perform 1 from public.icash_text_threads where id=g.thread_id and account_id=p_account for update;
 if not public.icash_seller_recovery_current(g.id) then return null;end if;
 if (select count(*) from public.icash_seller_recovery_attempts where account_id=p_account and thread_id=g.thread_id and assigned_at>now()-interval '7 days')>=3
 or exists(select 1 from public.icash_seller_recovery_attempts where account_id=p_account and thread_id=g.thread_id and (assigned_at>now()-interval '24 hours' or reason=g.reason and assigned_at>now()-interval '7 days')) then
  update public.icash_seller_gaps set state='needs_review',updated_at=now() where id=g.id;return null;
 end if;
 bucket:=((('x'||substr(md5(g.id::text),1,7))::bit(28)::integer)%10000);
 select variants.* into v from public.icash_seller_recovery_variants variants where enabled and key=coalesce(public.icash_seller_recovery_context_variant(p_account,g.id),
  (select variant from public.icash_seller_recovery_attempts where account_id=p_account and deal_id=g.deal_id and reason=g.reason and stage=g.stage and source_channel=g.channel and variant in (select key from public.icash_seller_recovery_variants where reason=g.reason) order by assigned_at,gap_id limit 1),
  public.icash_choose_seller_recovery(p_account,g.reason,g.stage,g.channel,bucket));
 if not found then update public.icash_seller_gaps set state='needs_review',updated_at=now() where id=g.id;return null;end if;
 mid:=public.icash_queue_text(p_account,g.thread_id,g.id,v.body,'{}');if mid is null then return null;end if;
 update public.icash_seller_gaps set state='queued',outgoing_id=mid,updated_at=now() where id=g.id;
 insert into public.icash_seller_recovery_attempts(gap_id,account_id,deal_id,thread_id,variant,reason,stage,source_channel,message_id)
 values(g.id,p_account,g.deal_id,g.thread_id,v.key,g.reason,g.stage,g.channel,mid);
 return mid;
end $function$

CREATE OR REPLACE FUNCTION public.icash_queue_text(p_account uuid, p_thread uuid, p_key uuid, p_body text, p_assets uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare t public.icash_text_threads;m public.icash_text_messages;urls jsonb;total bigint;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
select * into t from public.icash_text_threads where id=p_thread and account_id=p_account;
 if not found or t.retired_at is not null or not exists(select 1 from public.icash_deal_files where id=t.deal_id and account_id=p_account) then raise exception 'Thread not available';end if;
 if length(trim(p_body))=0 and cardinality(p_assets)=0 then raise exception 'Message required';end if;
 if length(p_body)>1000 or cardinality(p_assets)>3 then raise exception 'Message too large';end if;
 -- One SMS segment per reviewed rate; MMS has its own independent rate.
 if cardinality(p_assets)=0 and not public.icash_sms_single_segment(p_body) then raise exception 'Shorten the message';end if;
 select coalesce(jsonb_agg(url order by id),'[]'),coalesce(sum(bytes),0) into urls,total from public.icash_text_assets where id=any(p_assets) and account_id=p_account and deal_id=t.deal_id and verified_until>now();
 if jsonb_array_length(urls)<>cardinality(p_assets) or total>5000000 then raise exception 'Verified attachments required';end if;
 insert into public.icash_text_messages(thread_id,account_id,direction,body,asset_ids,attachments,state,request_key) values(t.id,p_account,'outgoing',p_body,p_assets,urls,'ready',p_key) on conflict(request_key) do nothing;
 select * into m from public.icash_text_messages where request_key=p_key;
 -- Insert uses the caller's idempotency key below; no cross-account lookup may return an ID.
 if m.id is null then raise exception 'Message key missing';end if;
 if m.account_id<>p_account or m.thread_id<>p_thread or m.body<>p_body or m.asset_ids<>p_assets then raise exception 'Message key conflict';end if;
 return m.id;
end $function$
